const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const projectRoot = path.resolve(__dirname, '..');
const tweaksRoot = path.join(projectRoot, 'resources', 'tweaks');
const outputPath = path.join(projectRoot, 'electron', 'generated', 'bundled-tweaks-manifest.js');

function listFiles(directory, baseDirectory = directory) {
  return fs.readdirSync(directory, { withFileTypes: true })
    .sort((left, right) => left.name.localeCompare(right.name))
    .flatMap((entry) => {
      const absolutePath = path.join(directory, entry.name);
      if (entry.isDirectory()) return listFiles(absolutePath, baseDirectory);
      if (!entry.isFile()) throw new Error(`Unsupported tweak resource entry: ${absolutePath}`);
      return [path.relative(baseDirectory, absolutePath).replace(/\\/g, '/')];
    });
}

function sha256(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

const files = Object.fromEntries(listFiles(tweaksRoot).map((relativePath) => {
  const content = fs.readFileSync(path.join(tweaksRoot, ...relativePath.split('/')));
  return [relativePath, { sha256: sha256(content), size: content.length }];
}));
const rootHash = sha256(Buffer.from(
  Object.entries(files).map(([name, value]) => `${name}\0${value.size}\0${value.sha256}`).join('\n'),
  'utf8'
));
const manifest = { schemaVersion: 1, rootHash, files };

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(
  outputPath,
  `// Generated by scripts/generate-bundled-tweak-manifest.js.\n// Do not edit manually.\nmodule.exports = ${JSON.stringify(manifest, null, 2)};\n`,
  'utf8'
);

console.log(`Bundled tweak manifest generated: ${Object.keys(files).length} files (${rootHash.slice(0, 12)}...).`);
